1#RH:<!DOCTYPE html>
2#MN:<html lang="en">
3#HW:<head>
4#HP:  <meta charset="UTF-8">
5#JY:  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6#WZ:  <meta name="color-scheme" content="light dark">
7#XB:  <title>CodeYourPCB Viewer</title>
8#MR:  <script>
9#SV:    // FART prevention: Flash of inAccurate coloR Theme
10#SY:    // Set theme BEFORE CSS loads to prevent flash of wrong theme
11#PW:    const savedTheme = localStorage.getItem('theme');
12#MX:    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
13#NT:    const theme = savedTheme === 'light' || savedTheme === 'dark' ? savedTheme : (systemPrefersDark ? 'dark' : 'light');
14#JM:    document.documentElement.setAttribute('data-theme', theme);
15#HQ:  </script>
16#PQ:  <style>
17#JJ:    * { margin: 0; padding: 0; box-sizing: border-box; }
18#SN:    body {
19#XP:      font-family: system-ui, sans-serif;
20#NR:      background: var(--bg-secondary);
21#XB:      color: var(--text-primary);
22#XQ:      height: 100vh;
23#WM:      display: flex;
24#MV:      flex-direction: column;
25#QR:      transition: background-color 0.15s ease, color 0.15s ease;
26#JZ:    }
27#NR:    label {
28#XB:      color: var(--text-primary);
29#MP:    }
30#SJ:    #toolbar {
31#WT:      background: var(--bg-elevated);
32#BS:      border-bottom: 1px solid var(--border-primary);
33#QT:      padding: 8px 16px;
34#WM:      display: flex;
35#YP:      gap: 16px;
36#YK:      align-items: center;
37#WZ:      transition: background-color 0.15s ease, border-color 0.15s ease;
38#KM:    }
39#MV:    #toolbar .separator {
40#RY:      color: var(--text-tertiary);
41#JM:      margin: 0 -8px;
42#ZS:    }
43#ZS:    /* Editor toggle button */
44#VH:    #editor-toggle {
45#NR:      background: var(--bg-secondary);
46#KN:      border: 1px solid var(--border-primary);
47#HP:      padding: 4px 12px;
48#JY:      border-radius: 4px;
49#VQ:      cursor: pointer;
50#PM:      font-size: 12px;
51#RX:      transition: background-color 0.15s;
52#WT:    }
53#XK:    #editor-toggle:hover {
54#ZQ:      background: var(--border-primary);
55#VH:    }
56#YT:    /* Divider between editor and canvas */
57#SS:    #divider:hover {
58#PY:      background: var(--accent-primary);
59#YZ:    }
60#JR:    #canvas-container {
61#PN:      flex: 1;
62#YQ:      position: relative;
63#YW:      overflow: hidden;
64#YJ:    }
65#BS:    #pcb-canvas {
66#TJ:      position: absolute;
67#MS:      top: 0;
68#VX:      left: 0;
69#YV:      touch-action: none;
70#HQ:    }
71#BM:    #status {
72#TJ:      position: absolute;
73#SM:      bottom: 8px;
74#RR:      left: 8px;
75#ZW:      background: var(--status-bg);
76#QB:      padding: 4px 8px;
77#JY:      border-radius: 4px;
78#PM:      font-size: 12px;
79#WM:      display: flex;
80#YK:      align-items: center;
81#BZ:      gap: 8px;
82#QR:      transition: background-color 0.15s ease, color 0.15s ease;
83#ZQ:    }
84#JN:    #error-badge {
85#ZP:      background: var(--error);
86#XM:      color: white;
87#NV:      padding: 2px 8px;
88#SS:      border-radius: 10px;
89#YT:      font-size: 11px;
90#VQ:      cursor: pointer;
91#KQ:    }
92#ZP:    #error-badge:hover {
93#VY:      filter: brightness(0.85);
94#PW:    }
95#BV:    #error-badge.hidden {
96#PM:      display: none;
97#WJ:    }
98#BM:    /* Error panel (VS Code style) */
99#RT:    #error-panel {
100#TJ:      position: absolute;
101#TN:      bottom: 40px;
102#RR:      left: 8px;
103#HY:      width: 350px;
104#NN:      max-height: 200px;
105#WT:      background: var(--bg-elevated);
106#KN:      border: 1px solid var(--border-primary);
107#JY:      border-radius: 4px;
108#PP:      box-shadow: 0 2px 8px var(--shadow);
