110#WZ:      transition: background-color 0.15s ease, border-color 0.15s ease;
111#JP:    }
112#BX:    #error-panel.hidden {
113#PM:      display: none;
114#MS:    }
115#MN:    #error-panel-header {
116#WN:      padding: 8px 12px;
117#NR:      background: var(--bg-secondary);
118#BS:      border-bottom: 1px solid var(--border-primary);
119#WM:      display: flex;
120#RZ:      justify-content: space-between;
121#YK:      align-items: center;
122#RW:      font-weight: 500;
123#TN:    }
124#JY:    #error-panel-close {
125#MB:      background: none;
126#JZ:      border: none;
127#QN:      font-size: 18px;
128#VQ:      cursor: pointer;
129#ZQ:      color: var(--text-secondary);
130#PN:    }
131#KS:    #error-panel-close:hover {
132#XB:      color: var(--text-primary);
133#YJ:    }
134#WP:    #error-list {
135#NV:      overflow-y: auto;
136#JM:      max-height: 160px;
137#BB:    }
138#ZY:    .error-item {
139#WN:      padding: 8px 12px;
140#SM:      border-bottom: 1px solid var(--border-secondary);
141#VQ:      cursor: pointer;
142#PM:      font-size: 12px;
143#NM:    }
144#RY:    .error-item:hover {
145#NR:      background: var(--bg-secondary);
146#VP:    }
147#TX:    .error-item:last-child {
148#KB:      border-bottom: none;
149#PN:    }
150#VH:    .error-kind {
151#ZN:      color: var(--error);
152#RW:      font-weight: 500;
153#MK:    }
154#JY:    .error-message {
155#XB:      color: var(--text-primary);
156#KW:    }
157#MS:    /* Open button */
158#RS:    #open-btn {
159#PY:      background: var(--accent-primary);
160#XM:      color: white;
161#JZ:      border: none;
162#HP:      padding: 4px 12px;
163#JY:      border-radius: 4px;
164#VQ:      cursor: pointer;
165#PM:      font-size: 12px;
166#RV:    }
167#KP:    #open-btn:hover {
168#ZH:      background: var(--accent-hover);
169#KB:    }
170#NY:    /* Share button */
171#XZ:    #share-btn {
