208#HT:    /* Cancel button */
209#PS:    #cancel-route-btn {
210#ZP:      background: var(--error);
211#XM:      color: white;
212#JZ:      border: none;
213#HP:      padding: 4px 12px;
214#JY:      border-radius: 4px;
215#VQ:      cursor: pointer;
216#PM:      font-size: 12px;
217#PW:    }
218#YH:    #cancel-route-btn:hover {
219#VY:      filter: brightness(0.85);
220#VS:    }
221#TB:    #cancel-route-btn.hidden {
222#PM:      display: none;
223#BH:    }
224#PJ:    #undo-btn, #redo-btn {
225#NR:      background: var(--bg-secondary);
226#KN:      border: 1px solid var(--border-primary);
227#QB:      padding: 4px 8px;
228#JY:      border-radius: 4px;
229#VQ:      cursor: pointer;
230#JV:      font-size: 13px;
231#XB:      color: var(--text-primary);
