1#RS:/**
2#VB: * JLCPCB / EasyEDA API Client
3#SZ: *
4#QY: * Two pipelines:
5#MS: * 1. Component search via tscircuit/jlcsearch (CORS-enabled, no auth)
6#ZH: * 2. 3D model fetch via EasyEDA API: LCSC ID → component data → 3D UUID → OBJ text
7#YW: */
8#XW:
9#SV:/** Component result from jlcsearch API */
10#HV:export interface JLCPCBComponent {
11#RR:  /** LCSC part number (bare integer, e.g. 17414 for C17414) */
12#KK:  lcsc: number;
13#PZ:  /** Manufacturer part number */
14#SZ:  mfr: string;
15#WB:  /** Package/footprint (e.g. "0805") */
16#RQ:  package: string;
17#KR:  /** Whether this is a JLCPCB basic part */
18#XR:  isBasic: boolean;
19#SJ:  /** Current stock count */
20#KT:  stock: number;
21#PT:  /** Unit price in USD */
22#YV:  price: number;
23#XQ:  /** Manufacturer name (from extra field) */
24#KW:  manufacturer: string;
25#WS:  /** Component attributes: resistance, capacitance, etc. (from extra field) */
26#XZ:  attributes: Record<string, string>;
27#YJ:  /** Datasheet PDF URL (from extra field) */
28#PH:  datasheetUrl: string;
29#NP:}
30#ZM:
31#MB:const JLCSEARCH_BASE = 'https://jlcsearch.tscircuit.com';
32#VR:const EASYEDA_API_BASE = 'https://easyeda.com';
33#NV:const EASYEDA_MODULES_BASE = 'https://modules.easyeda.com';
34#WV:
35#JS:/**
36#QQ: * Search JLCPCB/LCSC components via tscircuit jlcsearch API.
37#PB: * Returns typed results with parsed metadata from the `extra` JSON string.
38#BM: * Returns empty array on error — never throws.
39#YB: */
40#KT:export async function searchComponents(
41#WH:  query: string,
42#NZ:  limit = 20,
43#JP:): Promise<JLCPCBComponent[]> {
44#JQ:  try {
45#WP:    const params = new URLSearchParams({
46#NM:      q: query,
47#WQ:      limit: String(limit),
48#JP:      full: 'true',
49#NH:    });
50#QH:    const url = `${JLCSEARCH_BASE}/api/search?${params}`;
51#TZ:    const response = await fetch(url);
52#NM:
53#RB:    if (!response.ok) {
54#KS:      console.error(`[JLCPCB] Search error: HTTP ${response.status} for "${query}"`);
55#ST:      return [];
56#JH:    }
57#WH:
58#XV:    const data = await response.json();
59#QS:    const components = data?.components;
60#HQ:
61#YM:    if (!Array.isArray(components)) {
62#ST:      return [];
63#TN:    }
64#XZ:
65#XJ:    return components.map((raw: any) => parseSearchResult(raw));
66#QB:  } catch (error) {
67#RV:    console.error(`[JLCPCB] Search error: ${error}`);
68#HS:    return [];
69#YV:  }
70#BY:}
71#PR:
72#YW:/**
73#JR: * Fetch a 3D model OBJ text for a given LCSC part number.
74#SQ: * Pipeline: LCSC ID → EasyEDA component API → extract 3D UUID → fetch OBJ.
75#RK: * Returns null if no 3D model is available or on any error — never throws.
76#XJ: */
77#YW:export async function fetch3DModel(lcscId: number): Promise<string | null> {
78#JQ:  try {
79#HY:    // Step 1: Fetch component data from EasyEDA
80#KR:    const lcscStr = `C${lcscId}`;
81#BW:    const componentUrl =
82#HX:      `${EASYEDA_API_BASE}/api/products/${lcscStr}/components?version=6.4.19.5`;
83#VH:    const compResponse = await fetch(componentUrl);
84#WR:
85#BB:    if (!compResponse.ok) {
86#XJ:      console.error(`[JLCPCB] 3D fetch error: HTTP ${compResponse.status} for ${lcscStr}`);
87#BX:      return null;
88#KJ:    }
89#WY:
90#VS:    const compData = await compResponse.json();
91#RT:
92#YQ:    // Step 2: Extract 3D model UUID from shape array
93#RX:    const uuid = extract3DModelUUID(compData);
94#SZ:    if (!uuid) {
95#XR:      return null; // No 3D model available for this component
96#BZ:    }
97#ZT:
98#MV:    // Step 3: Fetch OBJ text
99#XQ:    const objUrl = `${EASYEDA_MODULES_BASE}/3dmodel/${uuid}`;
100#XP:    const objResponse = await fetch(objUrl);
101#ZS:
102#TN:    if (!objResponse.ok) {
103#JV:      console.error(`[JLCPCB] 3D fetch error: HTTP ${objResponse.status} for OBJ ${uuid}`);
104#BX:      return null;
105#HQ:    }
106#HT:
107#JW:    return await objResponse.text();
108#QB:  } catch (error) {
109#KZ:    console.error(`[JLCPCB] 3D fetch error: ${error}`);
110#MW:    return null;
111#VV:  }
112#HR:}
113#PP:
114#KX:/**
115#YT: * Parse a single search result from jlcsearch API, extracting the nested
116#JN: * `extra` JSON string into structured fields.
117#HB: */
118#WM:export function parseSearchResult(raw: any): JLCPCBComponent {
119#ZZ:  let manufacturer = '';
120#VS:  let attributes: Record<string, string> = {};
121#HM:  let datasheetUrl = '';
122#JQ:
123#TX:  if (raw.extra && typeof raw.extra === 'string') {
124#VN:    try {
125#PW:      const extra = JSON.parse(raw.extra);
126#JP:      manufacturer = extra?.manufacturer?.name ?? '';
127#VQ:      if (extra?.attributes && typeof extra.attributes === 'object') {
128#WV:        attributes = extra.attributes;
129#YZ:      }
130#NH:      datasheetUrl = extra?.datasheet?.pdf ?? '';
131#XP:    } catch {
132#WR:      // Malformed extra JSON — use defaults
133#YJ:    }
134#HB:  }
135#QX:
136#ZV:  return {
137#TY:    lcsc: typeof raw.lcsc === 'number' ? raw.lcsc : 0,
138#JT:    mfr: raw.mfr ?? '',
139#RT:    package: raw.package ?? '',
140#QR:    isBasic: raw.is_basic ?? false,
141#RM:    stock: typeof raw.stock === 'number' ? raw.stock : 0,
142#BR:    price: typeof raw.price === 'number' ? raw.price : 0,
143#HH:    manufacturer,
144#NN:    attributes,
145#PR:    datasheetUrl,
146#ZR:  };
147#MQ:}
148#SS:
149#TX:/**
150#BP: * Extract the 3D model UUID from EasyEDA component API response.
151#WN: * Searches the shape array in packageDetail.dataStr for an outline3D entry.
152#BJ: * Returns null if no 3D model is present.
153#MW: */
154#PY:export function extract3DModelUUID(compData: any): string | null {
155#JQ:  try {
156#WJ:    // EasyEDA v6 response structure
157#VJ:    const result = compData?.result;
158#RV:    if (!result) return null;
159#XK:
160#YT:    // Could be a single result or array of results
161#RQ:    const items = Array.isArray(result) ? result : [result];
162#VQ:
163#BB:    for (const item of items) {
164#PT:      const shapes = item?.packageDetail?.dataStr?.shape;
165#WT:      if (!Array.isArray(shapes)) continue;
166#QB:
167#PB:      for (const shape of shapes) {
168#JS:        if (typeof shape !== 'string') continue;
169#PN:
170#ZP:        // Shape entries are like "SVGNODE~{...}" — look for outline3D with uuid
171#XN:        if (shape.includes('outline3D') || shape.includes('3D')) {
172#QT:          const uuidMatch = shape.match(/"uuid"\s*:\s*"([a-f0-9]{32})"/i);
173#XT:          if (uuidMatch) {
174#VX:            return uuidMatch[1];
175#VB:          }
176#BV:        }
177#SS:      }
178#ZW:    }
179#JZ:
180#MW:    return null;
181#PZ:  } catch {
182#MW:    return null;
183#WN:  }
184#MZ:}
