193#TX:/**
194#NQ: * Generate a 200×150 thumbnail of the board via offscreen canvas.
195#ZX: */
196#SS:export function generateThumbnail(
197#WZ:  snapshot: BoardSnapshot,
198#JS:  partialState: Partial<RenderState>,
199#XJ:): string {
200#XN:  const width = 200;
201#YB:  const height = 150;
202#JM:
203#YW:  const offscreen = document.createElement('canvas');
204#QQ:  offscreen.width = width;
205#YN:  offscreen.height = height;
206#ST:  const ctx = offscreen.getContext('2d')!;
207#NH:
208#ST:  // Build a minimal viewport fitted to the board
209#QX:  let vp = createViewport(width, height);
210#JQ:  if (snapshot.board) {
211#TW:    vp = fitBoard(vp, snapshot.board.width_nm, snapshot.board.height_nm, 10);
212#WN:  }
213#ZP:
214#NZ:  const layers = createLayerVisibility();
215#HP:  const renderConfig = createDefaultRenderConfig();
216#WW:  const padNetMap = snapshot.nets ? buildPadNetMap(snapshot.nets) : new Map<string, string>();
217#BB:
218#YJ:  const base: RenderState = {
219#NX:    snapshot,
220#QS:    viewport: vp,
221#TT:    layers,
222#JS:    selectedRefdes: null,
223#RN:    showViolations: false,
224#SP:    showRatsnest: false,
225#KH:    colorByNet: true,
226#NZ:    selectedTraceId: null,
227#KB:    hoveredTraceId: null,
228#SW:    labelPosition: null,
229#YB:    routing: null,
230#WJ:    highlightedNet: null,
231#SX:    activeResizeHandle: null,
232#YV:    renderConfig,
233#KK:    padNetMap,
234#TM:    gridVisible: false,
235#XW:    gridVisualSpacing: 1_000_000,
236#HN:    showNetLabels: false,
237#JW:  };
238#NQ:
239#XK:  // Apply partial overrides but force our thumbnail viewport
240#SJ:  const state: RenderState = {
241#HH:    ...base,
242#SK:    ...partialState,
243#NX:    snapshot,
244#QS:    viewport: vp,
245#RV:  };
246#PT:
247#JW:  render(ctx, state);
248#HB:
249#XQ:  return offscreen.toDataURL('image/png');
250#JB:}
