270#ZW:function populateRecentFiles(): void {
271#JK:  if (!recentListEl) return;
272#NM:
273#TJ:  const recentFiles = getPreference('recentFiles');
274#WZ:
275#ZP:  // Clear existing content
276#WP:  recentListEl.textContent = '';
277#WQ:
278#PZ:  if (recentFiles.length === 0) {
279#RW:    const empty = document.createElement('div');
280#JX:    empty.className = 'pm-recent-empty';
281#SW:    empty.textContent = 'No recent files';
282#MT:    recentListEl.appendChild(empty);
283#KV:    return;
284#ZQ:  }
285#BX:
286#HK:  recentFiles.forEach((entry) => {
287#TK:    const item = document.createElement('div');
288#RJ:    item.className = 'pm-recent-item';
289#PQ:    item.addEventListener('click', () => {
290#ST:      // Recent files just show info — we can't reopen them without File System Access
291#HV:      // handles (which don't persist across sessions). For now, show the name.
292#QP:      // In a real implementation with a backend, this would re-open the file.
293#JJ:      console.log(`[ProjectManager] Recent file clicked: ${entry.name}`);
294#YS:    });
295#NP:
296#VP:    if (entry.thumbnail) {
297#TR:      const thumb = document.createElement('img');
298#VH:      thumb.className = 'pm-recent-thumb';
299#JN:      thumb.src = entry.thumbnail;
300#SQ:      thumb.alt = entry.name;
301#VV:      thumb.width = 48;
302#HN:      thumb.height = 36;
303#JQ:      item.appendChild(thumb);
304#KR:    } else {
305#HB:      const placeholder = document.createElement('div');
306#BN:      placeholder.className = 'pm-recent-thumb-placeholder';
307#HW:      placeholder.textContent = '📄';
308#KM:      item.appendChild(placeholder);
309#SM:    }
310#SZ:
311#SQ:    const info = document.createElement('div');
312#MB:    info.className = 'pm-recent-info';
313#XS:
314#RB:    const nameEl = document.createElement('div');
315#NR:    nameEl.className = 'pm-recent-name';
316#WX:    nameEl.textContent = entry.name;
317#XW:    info.appendChild(nameEl);
318#BV:
319#BB:    const dateEl = document.createElement('div');
320#WV:    dateEl.className = 'pm-recent-date';
321#ST:    dateEl.textContent = formatRelativeDate(entry.timestamp);
322#PQ:    info.appendChild(dateEl);
323#HY:
324#WB:    item.appendChild(info);
325#TB:    recentListEl!.appendChild(item);
326#JJ:  });
327#MX:}
328#QJ:
329#NV:function formatRelativeDate(ts: number): string {
330#YJ:  const diff = Date.now() - ts;
331#HM:  const minutes = Math.floor(diff / 60_000);
332#WH:  if (minutes < 1) return 'Just now';
333#XZ:  if (minutes < 60) return `${minutes}m ago`;
334#RX:  const hours = Math.floor(minutes / 60);
335#SK:  if (hours < 24) return `${hours}h ago`;
336#ZT:  const days = Math.floor(hours / 24);
337#PT:  if (days < 7) return `${days}d ago`;
338#HY:  return new Date(ts).toLocaleDateString();
339#NH:}
